import numpy as np

def check(D, n_max, L=1):
    sequence = []
    for n in range(1, n_max + 1):
        # Available intervals for y_n
        forbidden = []
        for m in range(1, n):
            y_m = sequence[m-1]
            forbidden.append((y_m - D/(m+n), y_m + D/(m+n)))

        # Sort forbidden intervals
        forbidden.sort()

        # Find the smallest value in [0, L] not in any forbidden interval
        current = 0.0
        found = False
        for start, end in forbidden:
            if start > current + 1e-12:
                # There's a gap between current and start
                # But we must also check if this gap is within [0, L]
                gap_start = current
                gap_end = min(start, L)
                if gap_end >= gap_start:
                    sequence.append(gap_start)
                    found = True
                    break
            current = max(current, end)
            if current >= L:
                break

        if not found:
            if current < L - 1e-12:
                sequence.append(L)
                found = True
            else:
                return False
    return True

